def build_case(seed):
    rng = random.Random(seed)
    gen = Gen(rng)
    for _ in range(rng.randint(4, 14)):
        gen.make()
    types_by_name = dict(gen.types)
    type_list = [types_by_name[n] for n in gen.order]

    machine = None
    state_names = message_maxsize = None
    if rng.random() < 0.5:
        state_names = ["ST%d" % i for i in range(rng.randint(2, 5))]
        types_by_name["__STATE__"] = {"name": "__STATE__", "kind": "enum",
                                      "values": list(state_names)}
        types_by_name["__MSG__"] = {"name": "__MSG__", "kind": "string",
                                    "maxsize": 2}
        type_list = [types_by_name["__STATE__"], types_by_name["__MSG__"]] + type_list

    names = gen.order
    modules = {}
    order_names = []
    for i in range(rng.randint(2, 6)):
        name = "M%d" % i
        params = []
        if machine is not None:
            params.append(["st", "__STATE__"])
            params.append(["msg", "__MSG__"])
        for j in range(rng.randint(0, 3)):
            params.append(["p%d" % j, rng.choice(names)])
        used = {p[0] for p in params}
        result_name = "res" if "res" not in used else "res2"
        result_type = rng.choice(names + ["__VOID__"])
        if machine is not None and "__VOID__" not in names:
            types_by_name["__VOID__"] = {"name": "__VOID__", "kind": "void"}
            type_list.append(types_by_name["__VOID__"])
            names = names + ["__VOID__"]
        modules[name] = {"name": name, "params": params,
                         "result": [result_name, result_type],
                         "requires": rng.choice([None, ["const", "B", True],
                                                 ["const", "B", False],
                                                 ["not", ["const", "B", True]]])}
        order_names.append(name)
    module_list = [modules[n] for n in order_names]

    calls = []
    for i, caller in enumerate(order_names):
        for callee in order_names[:i]:
            if rng.random() < 0.35:
                calls.append([caller, callee])
    pipes = []
    for target in order_names:
        for filter_name in order_names:
            if filter_name == target or rng.random() > 0.25:
                continue
            bind = {}
            for pname, tname in modules[filter_name]["params"]:
                candidates = [tp for tp, tt in modules[target]["params"]]
                if not candidates:
                    break
                bind[pname] = rng.choice(candidates)
            else:
                pipes.append({"target": target, "filter": filter_name, "bind": bind})
    if machine is not None:
        transitions = []
        seen_pairs = set()
        for _ in range(rng.randint(0, 10)):
            frm = rng.choice(state_names)
            to = rng.choice(state_names)
            command = "k%d" % len(transitions)
            if (frm, command) in seen_pairs:
                continue
            seen_pairs.add((frm, command))
            transitions.append({"from": frm, "to": to, "command": command,
                                "cost": rng.randint(1, 20),
                                "when": rng.choice([None, ["const", "B", True],
                                                    ["const", "B", False]])})
        machine = {"states": state_names, "initial": state_names[0],
                   "state_param": "st", "message_param": "msg",
                   "transitions": transitions}
        gen.add({"name": "B", "kind": "bool"})

    campaign = {"types": type_list, "modules": module_list, "calls": calls,
                "pipes": pipes, "entries": [rng.choice(order_names)
                                            for _ in range(rng.randint(1, 3))],
                "machine": machine, "runs": []}
    # ensure the bool type exists for predicate constants
    if "B" not in types_by_name:
        types_by_name["B"] = {"name": "B", "kind": "bool"}
        campaign["types"].append(types_by_name["B"])
    return campaign, gen, rng


def encode_run(campaign, gen, rng, entry, mutate=None):
    types_by_name = {t["name"]: t for t in campaign["types"]}
    modules = {m["name"]: m for m in campaign["modules"]}
    module = modules[entry]
    has_pipes = any(p["target"] == entry for p in campaign["pipes"])
    slots, flag, variables = oracle_layout(types_by_name, module, has_pipes)

    values, leaves = {}, {}
    for pname, tname in module["params"]:
        value, sub = gen.value(tname)
        values[pname] = value
        for path, leaf in sub.items():
            leaves[(pname,) + path] = leaf
    rname, rtname = module["result"]
    if types_by_name[rtname]["kind"] == "void":
        result = None
    else:
        result, sub = gen.value(rtname)
        for path, leaf in sub.items():
            leaves[(rname,) + path] = leaf

    objs = []
    for name, path, width, kind, tdef in slots:
        key = tuple(path)
        leaf_kind, int_value, leaf_width = leaves[key]
        assert leaf_width == width, (key, leaf_width, width)
        objs.append((name, int_value.to_bytes(width, "little")))
    if flag is not None:
        objs.append((flag, b"\x00"))

    expected_invalid = False
    if mutate:
        expected_invalid = mutate(objs, slots, flag, variables, rng, types_by_name,
                                  modules, campaign, entry, has_pipes)
    payload = {"entry": entry, "ktest": kit.encode(objs)}
    return payload, values, result, expected_invalid


def mutate_drop(objs, slots, flag, variables, rng, *rest):
    del objs[rng.randrange(len(objs))]
    return True


def mutate_duplicate(objs, slots, flag, variables, rng, *rest):
    objs.append(objs[rng.randrange(len(objs))])
    return True


def mutate_unknown(objs, slots, flag, variables, rng, *rest):
    known = {name for name, _ in objs}
    candidates = ["x%d" % i for i in range(variables + 4)
                  if "x%d" % i not in known]
    if not candidates:
        return False
    name = rng.choice(candidates)
    objs.append((name, b"\x00"))
    return True


def mutate_composite(objs, slots, flag, variables, rng, *rest):
    object_ids = {s[0] for s in slots} | ({flag} if flag else set())
    composites = [i for i in range(variables) if "x%d" % i not in object_ids]
    if not composites:
        return False
    objs.append(("x%d" % rng.choice(composites), b"\x00"))
    return True


def mutate_width(objs, slots, flag, variables, rng, *rest):
    index = rng.randrange(len(objs))
    name, data = objs[index]
    objs[index] = (name, data + b"\x00")
    return True


def mutate_leaf(objs, slots, flag, variables, rng, types_by_name, *rest):
    by_name = {s[0]: s for s in slots}
    candidates = [i for i, (name, data) in enumerate(objs)
                  if name in by_name and by_name[name][3] in ("bool", "enum", "int")]
    if not candidates:
        return False
    index = rng.choice(candidates)
    name, data = objs[index]
    slot = by_name[name]
    kind, tdef = slot[3], slot[4]
    if kind == "bool":
        objs[index] = (name, b"\x02")
    elif kind == "enum":
        objs[index] = (name, len(tdef["values"]).to_bytes(4, "little"))
    else:
        bits = tdef["bits"]
        width = width_of(tdef)
        if bits == width * 8:
            return False
        objs[index] = (name, (1 << bits).to_bytes(width, "little"))
    return True


def mutate_base64(objs, slots, flag, variables, rng, *rest):
    objs.append(("zz", b"\x00"))
    return True


